"use strict";(globalThis.webpackChunkgrc||=[]).push([[71088],{88642(e){e.exports=JSON.parse('{"citeKey":"wu2024autohet","slug":"wu-2024-autohet-51af","title":"AUTOHET: An Automated Heterogeneous ReRAM-Based Accelerator for DNN Inference","authors":["T. Wu","S. He","J. Zhu","W. Chen","S. Yang","P. Chen","Y. Yin","X. Zhang","X.-H. Sun","G. Chen"],"venue":"The 53th International Conference on Parallel Processing (ICPP\'24)","type":"Conference","entryType":"inproceedings","date":"August, 2024","year":2024,"era":"iit","month":8,"doi":"10.1145/3673038.3673143","abstract":"ReRAM-based accelerators have become prevalent in accelerating deep neural network inference owing to their in-situ computing ca- pability of ReRAM crossbars. However, most existing ReRAM-based accelerators are designed with homogeneous crossbars, leading to either low resource utilization or sub-optimal energy efficiency. In this paper, we propose AUTOHET, an automated heterogeneous ReRAM-based accelerator with varied-size crossbars for different DNN layers. To achieve both high crossbar utilization and energy efficiency, AUTOHET uses a reinforcement learning algorithm to automatically determine the proper crossbar configuration for each DNN layer. Additionally, AUTOHET introduces rectangle crossbars and a tile-shared crossbar allocation scheme to reduce crossbar wastage and energy consumption. Experiment results show that AUTOHET effectively improves crossbar utilization by up to 3.1\xd7 and reduces energy consumption by up to 94.6%, compared to ap- proaches with homogeneous ReRAM crossbars.","hasAbstract":true,"lede":"We propose AUTOHET, an automated heterogeneous ReRAM-based accelerator with varied-size crossbars for different DNN layers.","links":{"pdf":"https://grc.iit.edu/papers/2024/wu-2024-autohet-51af.pdf"},"tags":["Heterogeneous Systems","Emerging Architectures"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);